// Valheim → launch args (mechanism deployment-specific)
// ---------------------------------------------------------------------------

const VALHEIM_CONTAINER = "valheim";
const VALHEIM_IMAGE = "lloesche/valheim-server";
/** Ports + volumes exactly as prisma/catalog.ts's Valheim template provisions them. */
const VALHEIM_BASE_RUN_FLAGS =
  "-p 2456-2458:2456-2458/udp -v /opt/valheim/config:/config -v /opt/valheim/data:/opt/valheim --env-file /root/valheim.env";

/**
 * Own devcommands-fix plugin (tools/valheim-plugins/NxeonDevAdmin — source and
 * build instructions live there), bind-mounted straight into the image's own
 * "drop your plugins here" folder for every BepInEx-enabled server. Found live
 * 2026-09-09: the only actively-maintained third-party mod for this
 * ("Server devcommands") throws a HarmonyException on Awake() against the
 * current game build (a stale Harmony patch target — Undefined target method
 * for Container::RPC_OpenRespons), which aborts the WHOLE plugin's
 * initialization, not just that one feature. Our own plugin does exactly one
 * thing — a single Harmony postfix on Terminal.IsCheatsEnabled() using ZNet's
 * own already-public LocalPlayerIsAdminOrHost() check — verified against the
 * actual current game assembly (not guessed), so it has far less surface area
 * to break against a future game update than a multi-feature mod bundle.
 *
 * A bind mount (not an upload-then-restart step) so it's simply always
 * present from container start, with no dependency on BepInEx's own
 * install-then-copy timing on first boot.
 */
const VALHEIM_DEVADMIN_DLL_LOCAL = join(process.cwd(), "worker/assets/valheim/NxeonDevAdmin.dll");
const VALHEIM_DEVADMIN_VM_DIR = "/opt/valheim/nxeon-mods";
const VALHEIM_DEVADMIN_VM_PATH = `${VALHEIM_DEVADMIN_VM_DIR}/NxeonDevAdmin.dll`;

function valheimRunFlags(bepinexEnabled: boolean): string {
  if (!bepinexEnabled) return VALHEIM_BASE_RUN_FLAGS;
  return `${VALHEIM_BASE_RUN_FLAGS} -v ${VALHEIM_DEVADMIN_VM_DIR}:/config/bepinex/plugins/nxeon-dev-admin:ro`;
}

/**
 * World-modifier presets Valheim itself accepts, mirroring the `preset` field's
 * enum in lib/game-config.ts. `SERVER_ARGS` is expanded UNQUOTED by the image's
 * launch line, so this value must never be free text — `validateConfig` already
 * restricts it to the schema's options, and this allowlist is the second line of
 * defence rather than trusting that alone.
 */
const VALHEIM_PRESETS = new Set(["normal", "casual", "easy", "hard", "hardcore", "immersive", "hammer"]);
// Verified against the game's own known -modifier value set, not guessed —
// see lib/game-config.ts's deathpenalty/portals field comments.
const VALHEIM_DEATHPENALTY_VALUES = new Set(["casual", "veryeasy", "easy", "normal", "hard", "hardcore"]);
const VALHEIM_PORTALS_VALUES = new Set(["casual", "normal", "hard", "veryhard"]);
const VALHEIM_RAIDS_VALUES = new Set(["none", "muchless", "less", "normal", "more", "muchmore"]);

/**
 * Valheim → container recreation with an --env-file (NOT a launch-args file).
 *
 * Found live 2026-09-06 by the catalog sweep, and this was the worst-behaved of
 * the three pre-written apply functions: the previous version wrote a
 * `nxeon-launch-args.txt` next to the server binary and returned **ok: true**,
 * so the customer was notified "Game settings applied on <hostname>" while
 * nothing on the server had changed and nothing ever read that file. Its own
 * TODO admitted as much ("wire the start script/systemd unit to source this
 * file") — but a TODO does not stop `ok: true` reaching a customer. Exactly the
 * "asserting an outcome it never performed" failure this module's header calls
 * out.
 *
 * The real mechanism, read off the running container's own
 * `/usr/local/bin/valheim-server`:
 *
 *   "$valheim_server" -nographics -batchmode -name "$SERVER_NAME" \
 *     -port "$SERVER_PORT" -world "$WORLD_NAME" -public "$SERVER_PUBLIC" \
 *     "${valheim_server_args[@]}" $SERVER_ARGS
 *
 * So `world` is `WORLD_NAME`, and `preset` — which has no variable of its own —
 * goes through `SERVER_ARGS`, the image's own pass-through for extra flags.
 */
async function applyValheim(conn: Client, sftp: SFTPWrapper, v: Values, gameVariant: string): Promise<ApplyOutcome> {
  const envMap = await readContainerEnv(conn, VALHEIM_CONTAINER);
  if (!envMap) {
    return { ok: false, applied: [], notes: [`Could not find the "${VALHEIM_CONTAINER}" container — nothing was changed.`] };
  }

  const applied: string[] = [];
  const notes: string[] = [];

  // BepInEx variant switch — found live 2026-09-09: `Server.gameVariant`
  // (lib/game-config.ts's vanilla/bepinex choice) was never applied for any
  // family post-provision, ANYWHERE in this codebase — worker/game-variant.ts's
  // applyGameVariant is provision-time-only and Minecraft-only, and
  // gameConfigApply resolves `variant` but never threads it into a family's
  // real-apply function. So picking "BepInEx" in Settings on an already-running
  // Valheim server did nothing at all. lloesche/valheim-server has this built
  // in already (`-e BEPINEX=true`, verified against its own README): it
  // downloads BepInExPack Valheim from Thunderstore, creates
  // /config/bepinex/plugins for user-added mods, and copies them into the
  // real plugin dir on boot — no custom bootstrap needed here, just wiring
  // the flag through. Diff-guarded like SERVER_PASS above: only recreate when
  // the setting genuinely differs from what's running.
  const wantsBepinex = gameVariant === "bepinex";
  const currentBepinex = envMap.get("BEPINEX") === "true";
  if (wantsBepinex !== currentBepinex) {
    envMap.set("BEPINEX", wantsBepinex ? "true" : "false");
    applied.push(wantsBepinex ? "bepinex-enabled" : "bepinex-disabled");
  }

  // CROSSPLAY — found live 2026-09-15 via a real customer ticket (a PS5
  // player couldn't join): lib/game-config.ts's CROSSPLAY field has existed
  // since this schema shipped and lets a customer flip it on in Settings, but
  // nothing here ever applied it to the real container — same class of bug
  // as BEPINEX above (a schema field with no real-apply wiring). Confirmed
  // live: this customer's gameConfig said CROSSPLAY: true, but `docker
  // inspect` showed no CROSSPLAY env var on the actual running container at
  // all. lloesche/valheim-server's own docs: `-e CROSSPLAY=true` switches
  // Steam matchmaking to PlayFab so Xbox/PlayStation/Microsoft Store clients
  // can join. Same diff-guard shape as BEPINEX — only recreate when it
  // genuinely differs from what's running.
  if (v["CROSSPLAY"] != null) {
    const wantsCrossplay = bool(v["CROSSPLAY"]) === "true";
    const currentCrossplay = envMap.get("CROSSPLAY") === "true";
    if (wantsCrossplay !== currentCrossplay) {
      envMap.set("CROSSPLAY", wantsCrossplay ? "true" : "false");
      applied.push(wantsCrossplay ? "crossplay-enabled" : "crossplay-disabled");
    }
  }

  // Diff-guarded like SERVER_PASS below — found live 2026-09-11 via a real
  // customer's data-loss incident: this used to set WORLD_NAME unconditionally
  // on every Settings save, since the form always resends every field (its
  // `world` value comes from the STORED gameConfig, which may not match what's
  // actually running — e.g. the provisioning-time envKey fix above was applied
  // after this customer's server, or an earlier save already switched it).
  // Saving one unrelated field (their death penalty) silently switched their
  // live world to that stored value, starting a brand-new empty world and
  // orphaning their real one. Only recreate for `world` when it genuinely
  // differs from what the container is CURRENTLY running.
  const desiredWorld = v["world"] != null ? String(v["world"]).trim() : "";
  if (desiredWorld.length > 0 && envMap.get("WORLD_NAME") !== desiredWorld) {
    envMap.set("WORLD_NAME", desiredWorld);
    applied.push("world");
  }
  if (v["preset"] != null) {
    const preset = String(v["preset"]);
    if (!VALHEIM_PRESETS.has(preset)) {
      notes.push(`Ignored an unrecognised world preset "${preset}".`);
    } else {
      const args = envMap.get("SERVER_ARGS") ?? "";
      envMap.set("SERVER_ARGS", upsertArg(args, "-preset", preset));
      applied.push("preset");
    }
  }
  // Individual modifier overrides — same shape as `preset` above, just a
  // two-token flag (`-modifier <name> <value>`); upsertArg's literal-match
  // already handles a multi-word flag string correctly.
  for (const [key, modifierName, valid] of [
    ["deathpenalty", "deathpenalty", VALHEIM_DEATHPENALTY_VALUES] as const,
    ["portals", "portals", VALHEIM_PORTALS_VALUES] as const,
    ["raids", "raids", VALHEIM_RAIDS_VALUES] as const,
  ]) {
    if (v[key] == null) continue;
    const value = String(v[key]);
    if (!valid.has(value)) {
      notes.push(`Ignored an unrecognised ${key} value "${value}".`);
      continue;
    }
    const args = envMap.get("SERVER_ARGS") ?? "";
    // "normal" is this field's default/no-override choice in our own
    // dropdown, but Valheim's own -modifier parser doesn't accept "normal"
    // as an explicit value at all — found live 2026-09-09 via a real
    // customer's BepInEx log: "Could not parse 'deathpenalty' with a value
    // of 'normal' as a world modifier" (same for portals). The active
    // -preset already sets both to their default when no override is
    // present, so "Normal" here means "no override," not "pass the literal
    // word" — strip the flag instead of setting it to a value the game
    // itself rejects.
    envMap.set("SERVER_ARGS", value === "normal" ? removeArg(args, `-modifier ${modifierName}`) : upsertArg(args, `-modifier ${modifierName}`, value));
    applied.push(key);
  }
  // SERVER_PASS: found live 2026-09-08 — every Valheim server shared the
  // catalog's hardcoded 'changeme12' join password (prisma/catalog.ts) with
  // no schema field to change it (lib/game-config.ts's new SERVER_PASS
  // field). Only diff-guard on the actual env value, not "was it provided" —
  // Settings always resends every field on save, so an unconditional set
  // would recreate the container (a real player-facing restart) on every
  // unrelated settings change too.
  if (v["SERVER_PASS"] != null) {
    const desired = String(v["SERVER_PASS"]);
    if (desired.trim().length > 0 && envMap.get("SERVER_PASS") !== desired) {
      envMap.set("SERVER_PASS", desired);
      applied.push("password");
    }
  }
  // Self-healing, not just a one-shot side effect of toggling BepInEx on:
  // a customer already on the bepinex variant (from before this feature
  // shipped, or any earlier recreate that predates it) would otherwise never
  // pick up the plugin mount, since nothing else about their settings changed
  // to avoid the early-return below. Check the LIVE container's own mounts
  // (not just our env-map diff) so this repairs itself the next time
  // settings are saved for any reason, same pattern as Minecraft's
  // stale-image self-heal.
  let devAdminMountMissing = false;
  if (wantsBepinex) {
    const mounts = await execRemote(conn, `docker inspect ${VALHEIM_CONTAINER} --format '{{json .Mounts}}' 2>/dev/null`);
    devAdminMountMissing = mounts.code !== 0 || !mounts.stdout.includes(VALHEIM_DEVADMIN_VM_DIR);
    if (devAdminMountMissing) applied.push("devcommands-fix-deployed");
  }

  if (applied.length === 0) {
    return { ok: true, applied: [], notes: notes.length ? notes : ["No changes to apply."] };
  }

  await writeEnvFile(conn, sftp, "/root/valheim.env", envMap);

  if (wantsBepinex) {
    try {
      await execRemote(conn, `mkdir -p ${VALHEIM_DEVADMIN_VM_DIR}`);
      await sftpWriteBinary(sftp, VALHEIM_DEVADMIN_VM_PATH, readFileSync(VALHEIM_DEVADMIN_DLL_LOCAL));
    } catch (e) {
      // Never block the rest of the settings apply over this — worst case the
      // customer's server comes up BepInEx-enabled without our plugin, same
      // as before this feature existed.
      notes.push(`Could not deploy the built-in devcommands fix: ${String(e instanceof Error ? e.message : e).slice(0, 160)}`);
    }
  }

  const res = await recreateGameContainer(conn, {
    family: "valheim",
    container: VALHEIM_CONTAINER,
    runFlags: valheimRunFlags(wantsBepinex),
    image: VALHEIM_IMAGE,
  });
  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };

  if (applied.includes("world")) {
    notes.push("A new world name starts a fresh world — your previous world is still saved and comes back if you set the old name again.");
  }
  if (applied.includes("bepinex-enabled")) {
    notes.push(
      "BepInEx is installing now (a one-time download, can take a few minutes on first boot). " +
        "Admin-listed players (adminlist.txt) can already use devcommands once it's up — no extra mod needed. " +
        "Drop other plugin files into your server's /opt/valheim/config/bepinex/plugins folder via File Manager to install more mods."
    );
  } else if (applied.includes("devcommands-fix-deployed")) {
    notes.push("Admin-listed players (adminlist.txt) can now use devcommands — no extra mod needed.");
  }
  notes.push("Your server restarted to apply these — players can rejoin once it finishes loading.");

  return { ok: true, applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`], notes };
}

// ---------------------------------------------------------------------------
// CS2 → server.cfg (cvars) + launch-only notes
// ---------------------------------------------------------------------------

      help: "server.seed — 0 picks a random seed. Changing regenerates the map.",
    },
  ],
};

const VALHEIM: FamilySchema = {
  family: "valheim",
  label: "Valheim",
  defaultVariant: "vanilla",
  variants: [
    { id: "vanilla", label: "Vanilla", description: "Standard dedicated server." },
    { id: "bepinex", label: "BepInEx", description: "BepInEx modding framework for Valheim mods." },
  ],
  // Valheim dedicated-server launch args + world modifiers.
  fields: [
    // Found live 2026-09-08: prisma/catalog.ts's valheim setupScript hardcodes
    // `-e SERVER_PASS='changeme12'` with no schema field for it at all — every
    // Valheim customer on the platform was silently sharing that ONE join
    // password, with no way to see or change it (a real customer ticket: "I
    // don't see the server password anywhere, can I change it?"). `required`
    // so checkout forces a real value in from day one, same precedent as
    // DST's TOKEN field above.
    {
      key: "SERVER_PASS",
      label: "Server password",
      group: "General",
      type: "string",
      default: "",
      phase: "deploy",
      required: true,
      help: "Players need this to join. Valheim requires at least 5 characters.",
    },
    {
      key: "world",
      envKey: "WORLD_NAME",
      label: "World name",
      group: "World",
      type: "string",
      default: "Dedicated",
      phase: "deploy",
      help: "-world — the save file to load. A new name creates a fresh world.",
    },
    {
      key: "preset",
      label: "World modifier preset",
      group: "World",
      type: "enum",
      default: "normal",
      // applyValheim is always a full container recreate for any field change —
      // there is no live push mechanism at all (2026-09-10 audit).
      phase: "deploy",
      options: [
        { value: "normal", label: "Normal" },
        { value: "casual", label: "Casual" },
        { value: "easy", label: "Easy" },
        { value: "hard", label: "Hard" },
        { value: "hardcore", label: "Hardcore" },
        { value: "immersive", label: "Immersive" },
        { value: "hammer", label: "Hammer (creative)" },
      ],
      help: "-preset — global combat/resource modifiers.",
    },
    // Individual modifier overrides, distinct from the combined `preset`
    // above — Valheim itself lets these be tuned independently of whichever
    // preset is active. Values verified against the game's own known
    // -modifier value set (not guessed): deathpenalty accepts casual/
    // veryeasy/easy/normal/hard/hardcore, portals accepts casual/normal/
    // hard/veryhard. Requested directly by a customer 2026-09-09.
    {
      key: "deathpenalty",
      label: "Death penalty",
